import{_ as t,c as a,o as i,ag as o}from"./chunks/framework.CmfACxb0.js";const p=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1753017046000}'),n={name:"guide/index.md"};function r(s,e,l,u,d,h){return i(),a("div",null,e[0]||(e[0]=[o('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><strong>Toney</strong> is a fast, lightweight, terminal-based note-taking app for the modern developer. Built with <a href="https://charm.sh/" target="_blank" rel="noreferrer">Bubbletea</a>, Toney brings a sleek TUI interface with markdown rendering, file navigation, and native Neovim editing – all in your terminal.</p><h2 id="what-is-toney" tabindex="-1">What <em>is</em> Toney? <a class="header-anchor" href="#what-is-toney" aria-label="Permalink to &quot;What _is_ Toney?&quot;">​</a></h2><p>Toney is a lightweight TUI that lets you:</p><ul><li>Take quick notes without leaving the terminal</li><li>Organize and edit notes in Markdown</li><li>Track your Daily Tasks</li><li>Customize the app for <em>you</em> with a simple TOMl file</li></ul><p>No GUI bloat, just a minimalist note-taking app - fast and most importantly, <em>yours</em>.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Terminal-first</strong>: Made for the beginners and vim-guru&#39;s in mind. We abhor the mouse.</li><li><strong>Markdown-based</strong>: Store notes in plain md file, with beautiful styling. Which you can customize, <em>obviously</em>.</li><li><strong>Daily Tasks</strong>: Create and keep a record of your daily tasks, level up your productivity.</li><li><strong>Configurable</strong>: Configure everything from styles to keybinds, I mean, who doesn&#39;t love that?</li></ul><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><p>→ Jump to the <a href="/Toney/guide/install.html">Installation</a> section to start taking notes today.<br> → Or peek into the <a href="/Toney/config/">Configuration</a> page to make Toney your own.</p><br><p><em>Toney is built by <a href="https://github.com/NucleoFusion" target="_blank" rel="noreferrer">NucleoFusion</a>, with love for the terminal.</em></p>',12)]))}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
